const fail = (status, m, codigo) => [{ json: { ok: false, status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];
const falta = ["ERPNEXT_DOMAIN", "ERPNEXT_API_KEY", "ERPNEXT_API_SECRET"].filter(k => !$env[k]);
if (falta.length) return fail(500, 'PENDENTE_CONFIGURACAO_RITMO: variáveis ausentes no ambiente do Harmonia: ' + falta.join(', '), 'PENDENTE_CONFIGURACAO_RITMO');
return [{ json: { ok: true } }];

// Janela de dados pro indicador 'frete' (série dos últimos 7 dias, usada no
// gráfico de barras do Painel) e pro indicador 'freteVolume' (total do mês
// corrente, conforme o texto original do pendente: 'fretes emitidos por
// semana' e 'fretes emitidos no mês'). Uma única consulta ao Ritmo cobre os
// dois: busca desde a MENOR das duas datas (início do mês ou 7 dias atrás),
// e o nó 'Monta resposta' separa os dois agregados a partir da mesma lista.
const agora = new Date();
const inicioMes = new Date(Date.UTC(agora.getUTCFullYear(), agora.getUTCMonth(), 1)).toISOString().slice(0, 10);
const seteDiasAtras = new Date(agora.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
const desde = seteDiasAtras < inicioMes ? seteDiasAtras : inicioMes;
return [{ json: { ok: true, inicioMes, seteDiasAtras, desde, mesVigente: inicioMes.slice(0, 7) } }];

// O indicador 'ia' depende da Lyra Central, não do Ritmo — por isso a
// checagem é isolada aqui, em vez de bloquear o endpoint inteiro em
// 'Valida configuração'. Se a Lyra não estiver configurada neste Harmonia,
// os outros indicadores (frete/freteVolume/freteSaldo) seguem normalmente;
// só 'ia' fica como pendência.
const falta = ['LYRA_CENTRAL_URL', 'LYRA_API_KEY', 'LYRA_TENANT_ID'].filter(k => !$env[k]);
if (falta.length) return [{ json: { lyraConfigurada: false, motivo: 'Lyra Central não configurada neste Harmonia — variáveis ausentes: ' + falta.join(', ') + '.' } }];
return [{ json: { lyraConfigurada: true } }];

// ---------------------------------------------------------------------
// Synapse — Consumo — Serviços: monta a resposta final combinando os três
// indicadores (ia, frete/freteVolume, freteSaldo), cada um resolvido de
// forma independente nos nós anteriores. Regra central desta correção:
// NUNCA retornar 501 incondicional e NUNCA declarar um indicador como
// disponível sem um valor efetivamente obtido de uma fonte real.
// ---------------------------------------------------------------------
const periodo = $node['Calcula período'].json;
const mesVigente = periodo.mesVigente;

const pendencias = [];
const fontes = {};

function classificarErroRitmo(res) {
  const e = (res && res.error) || res || {};
  const upstream = Number(e.httpCode || e.statusCode || e.status || (e.cause && e.cause.status) || 0);
  if (upstream === 401 || upstream === 403) {
    return { codigo: 'FALHA_AUTENTICACAO', detalhe: 'Falha de autenticação/permissão ao consultar o Ritmo (HTTP ' + upstream + ').' };
  }
  return { codigo: 'FALHA_COMUNICACAO', detalhe: 'Falha de comunicação com o Ritmo' + (upstream ? ' (HTTP ' + upstream + ')' : '') + '.' };
}

function classificarErroLyra(res) {
  const e = (res && res.error) || res || {};
  const upstream = Number(e.httpCode || e.statusCode || e.status || (e.cause && e.cause.status) || 0);
  if (upstream === 401 || upstream === 403) {
    return { codigo: 'FALHA_AUTENTICACAO', detalhe: 'Falha de autenticação na Lyra Central (HTTP ' + upstream + ').' };
  }
  if (upstream === 429) {
    return { codigo: 'FALHA_COMUNICACAO', detalhe: 'Lyra Central recusou a consulta por limite de requisições (HTTP 429).' };
  }
  return { codigo: 'FALHA_COMUNICACAO', detalhe: 'Falha de comunicação com a Lyra Central' + (upstream ? ' (HTTP ' + upstream + ')' : '') + '.' };
}

// ---- freteSaldo (Synapse Credencial Externa — melhorenvio, cache real) ----
let freteSaldo = 'indisponível';
const credRes = $node['Ritmo — Credenciais de envio'].json;
if (credRes && credRes.error) {
  const c = classificarErroRitmo(credRes);
  pendencias.push({ campo: 'freteSaldo', codigo: c.codigo, detalhe: c.detalhe });
} else {
  const lista = (credRes && credRes.data) || [];
  const me = lista.find(r => r.provedor === 'melhorenvio' && r.status === 'conectado') || null;
  if (me && me.saldo) {
    freteSaldo = me.saldo;
    fontes.freteSaldo = 'Synapse Credencial Externa (melhorenvio).saldo — cache atualizado em ' + (me.cache_atualizado_em || 'data desconhecida') + '.';
  } else {
    pendencias.push({
      campo: 'freteSaldo',
      codigo: 'PENDENTE_FONTE_DE_DADOS',
      detalhe: me ? 'Melhor Envio está conectado, mas o cache de saldo no Ritmo está vazio.' : 'Melhor Envio não está conectado no Ritmo.'
    });
  }
}

// ---- frete (série dos últimos 7 dias) e freteVolume (total do mês) ----
// Fonte: Sales Invoice.custom_tracking_code, gravado pelo W2_logistica.json
// no despacho via Melhor Envio. Ver nota de dependência no nó anterior:
// este campo não está confirmado como provisionado pelos instaladores.
let frete = [];
let freteVolume = 'indisponível';
const fretesRes = $node['Ritmo — Fretes do período'].json;
if (fretesRes && fretesRes.error) {
  const e = fretesRes.error || {};
  const raw = String(e.description || e.message || '');
  const pareceCampoInexistente = /custom_tracking_code/i.test(raw) || /unknown column/i.test(raw) || /not a valid (field|fieldname)/i.test(raw);
  if (pareceCampoInexistente) {
    const d = 'O campo custom_tracking_code não está provisionado em Sales Invoice neste Ritmo (dependência: Custom Field ainda não criado pelo instalador). Fretes e volume de fretes não podem ser apurados até essa dependência ser resolvida.';
    pendencias.push({ campo: 'frete', codigo: 'FONTE_NAO_CONFIGURADA', detalhe: d });
    pendencias.push({ campo: 'freteVolume', codigo: 'FONTE_NAO_CONFIGURADA', detalhe: d });
  } else {
    const c = classificarErroRitmo(fretesRes);
    pendencias.push({ campo: 'frete', codigo: c.codigo, detalhe: c.detalhe });
    pendencias.push({ campo: 'freteVolume', codigo: c.codigo, detalhe: c.detalhe });
  }
} else {
  const lista = (fretesRes && fretesRes.data) || [];
  // Defesa extra (comportamento não confirmado contra uma instância real,
  // ver ressalva nos testes): se o Ritmo devolvesse 200 mesmo com a coluna
  // ausente, os itens não trariam a chave custom_tracking_code.
  const campoAusente = lista.length > 0 && lista.every(r => !Object.prototype.hasOwnProperty.call(r, 'custom_tracking_code'));
  if (campoAusente) {
    const d = 'A consulta ao Ritmo foi concluída, mas os registros devolvidos não trazem o campo custom_tracking_code — sinal de que ele não está provisionado em Sales Invoice. Fretes e volume de fretes não podem ser apurados até essa dependência ser resolvida.';
    pendencias.push({ campo: 'frete', codigo: 'FONTE_NAO_CONFIGURADA', detalhe: d });
    pendencias.push({ campo: 'freteVolume', codigo: 'FONTE_NAO_CONFIGURADA', detalhe: d });
  } else {
    freteVolume = lista.filter(r => (r.creation || '').slice(0, 10) >= periodo.inicioMes).length;
    const porDia = {};
    for (const r of lista) {
      const dia = (r.creation || '').slice(0, 10);
      if (dia >= periodo.seteDiasAtras) porDia[dia] = (porDia[dia] || 0) + 1;
    }
    frete = Object.keys(porDia).sort().map(dia => ({ d: dia.slice(8, 10) + '/' + dia.slice(5, 7), v: porDia[dia] }));
    fontes.frete = 'Sales Invoice.custom_tracking_code (Ritmo) — últimos 7 dias, por data de criação (campo zerado = consulta concluída sem fretes no dia, não ausência de dado).';
    fontes.freteVolume = 'Sales Invoice.custom_tracking_code (Ritmo) — total desde ' + periodo.inicioMes + ' (mês vigente).';
  }
}

// ---- ia (Lyra Central — GET /v1/usage/:tenantId) ----
let ia = [];
const lyraCfg = $node['Lyra configurada? (checagem)'].json;
if (!lyraCfg.lyraConfigurada) {
  pendencias.push({ campo: 'ia', codigo: 'FONTE_NAO_CONFIGURADA', detalhe: lyraCfg.motivo });
} else {
  let lyraRes = null;
  try { lyraRes = $node['Lyra — Consultar uso IA'].json; } catch (e) { lyraRes = null; }
  if (!lyraRes) {
    pendencias.push({ campo: 'ia', codigo: 'FALHA_COMUNICACAO', detalhe: 'Não foi possível obter resposta da Lyra Central.' });
  } else if (lyraRes.error) {
    const c = classificarErroLyra(lyraRes);
    pendencias.push({ campo: 'ia', codigo: c.codigo, detalhe: c.detalhe });
  } else if (lyraRes.status_cota === 'nao_implementado' || lyraRes.atendimentos_usados === null || lyraRes.atendimentos_usados === undefined) {
    pendencias.push({
      campo: 'ia',
      codigo: 'FONTE_NAO_IMPLEMENTADA',
      detalhe: 'A Lyra Central respondeu, mas o indicador de consumo de IA ainda não está implementado do lado dela (status_cota=' + (lyraRes.status_cota || 'desconhecido') + ').'
    });
  } else {
    ia = [{ d: lyraRes.mes_vigente || mesVigente, v: Number(lyraRes.atendimentos_usados) }];
    fontes.ia = 'Lyra Central GET /v1/usage/{tenant_id} — atendimentos_usados do mês vigente (granularidade mensal, não diária: um único ponto por mês).';
  }
}

// ---- Decide status/HTTP final ----
const completo = pendencias.length === 0;
const nadaObtido = ia.length === 0 && frete.length === 0 && freteVolume === 'indisponível' && freteSaldo === 'indisponível';
const todasFalhasDeComunicacao = pendencias.length > 0 && pendencias.every(p => p.codigo === 'FALHA_COMUNICACAO' || p.codigo === 'FALHA_AUTENTICACAO');
const falhaTotal = nadaObtido && todasFalhasDeComunicacao;

const status = completo ? 'OK' : (falhaTotal ? 'FALHA_COMUNICACAO' : 'PARCIAL');
const httpStatus = falhaTotal ? 502 : 200;
const msg = completo
  ? null
  : (falhaTotal
    ? 'Não foi possível consultar nenhuma fonte de consumo agora.'
    : 'Consumo de serviços obtido parcialmente — indisponível(is): ' + pendencias.map(p => p.campo).join(', ') + '.');

const body = {
  sucesso: completo,
  status,
  periodo: { mesVigente, seteDiasAtras: periodo.seteDiasAtras },
  ia,
  frete,
  freteSaldo,
  freteVolume
};
if (Object.keys(fontes).length) body.fontes = fontes;
if (pendencias.length) body.pendencias = pendencias;
if (msg) { body.erro = msg; body.message = msg; }

return [{ json: { status: httpStatus, body } }];
